INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(1, 1, 2, 4, 1, 'organizational', 'Tekken 7  Tournament', 'Step into the electrifying world of Tekken 7 at our thrilling tournament! Immerse yourself in the intense battles of this iconic fighting game, where skilled warriors clash for glory. Whether you\'re a seasoned fighter or a newcomer looking to test your skills, join us for an adrenaline-fueled event filled with competition, camaraderie, and epic moments. Bring your A-game, choose your favorite character, and let the showdown begin in this Tekken 7 Tournament - an unforgettable celebration of gaming prowess and community spirit!', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(2, NULL, NULL, 1, 2, 'open', 'Intramurals 2023-2024', 'Get ready to ignite the spirit of competition at the Intramurals 2023-2024! Join us for an action-packed extravaganza of sportsmanship, teamwork, and pure fun. From heart-pounding matches to friendly rivalries, this event is your chance to showcase your skills and embrace the thrill of intramural sports. Whether you\'re a seasoned athlete or a first-timer, there\'s a game for everyone. So, rally your friends, don your team colors, and let the games begin! The Intramurals 2023-2024 promises to be a memorable journey of camaraderie, sportsmanship, and the joy of playing together.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(3, NULL, NULL, 4, 3, 'open', 'Student Leadership Seminar', 'Embark on a transformative journey at our Student Leadership Seminar! Join us for an inspiring day filled with insights, skill-building, and networking opportunities designed to unleash the leader within you. Whether you\'re an aspiring student leader or looking to enhance your leadership capabilities, this seminar is your gateway to discovering effective strategies, fostering teamwork, and making a positive impact. Engage in dynamic discussions, learn from seasoned leaders, and cultivate the skills that will empower you to lead with confidence. Elevate your leadership potential at the Student Leadership Seminar – where tomorrow\'s leaders are shaped today.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(4, 1, NULL, 4, 4, 'departmental', 'Montes Progue: Software Testing Talk', 'This event is a unique opportunity to explore the intricacies of software testing, featuring expert insights, industry best practices, and the latest advancements in the field. Whether you\'re a seasoned QA professional, a software developer interested in testing methodologies, or a curious enthusiast, join us for an engaging discussion on ensuring software reliability, functionality, and user satisfaction. Uncover the secrets of effective testing strategies, learn from experienced practitioners, and discover how software testing plays a pivotal role in delivering top-notch products. Montes Progue: Software Testing Talk is your gateway to mastering the art and science of software testing.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(5, NULL, NULL, 5, NULL, 'open', 'Z League', 'Gear up for the ultimate showdown at Z League – where competition meets adrenaline! Join us for an exhilarating event that transcends the ordinary, bringing together the best in skill, strategy, and sportsmanship. Whether you\'re a player, a fan, or just seeking an unforgettable experience, Z League promises heart-pounding moments and electrifying matchups. From esports battles to physical challenges, this event is a celebration of talent, camaraderie, and the pursuit of victory. Don\'t miss your chance to be part of the Z League excitement – where champions are crowned, and memories are made! Get ready to witness the thrill of Z League, where the game is more than a competition; it\'s an experience like no other.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(6, NULL, NULL, 2, NULL, 'open', 'Baguio-Benguet Educational Athletic League', 'Join us for a captivating event that blends the thrill of athletic competition with the pursuit of intellectual achievement. Students from Baguio and Benguet will showcase their talents and dedication in a range of sports, fostering camaraderie and healthy competition. Beyond the playing field, witness the convergence of minds in quizzes, debates, and academic challenges, creating an all-encompassing celebration of holistic development. Come and be part of this exciting journey where education and athleticism unite in the picturesque landscapes of Baguio and Benguet. The Baguio-Benguet Educational Athletic League is not just a competition; it\'s a platform for growth, learning, and the forging of lifelong connections.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(7, NULL, NULL, 1, NULL, 'university', 'Food and Entertainment Fair', 'Savor the flavor and soak in the entertainment at our Food and Entertainment Fair! Indulge your taste buds in a culinary adventure featuring a diverse array of delectable cuisines from local vendors and talented chefs. As you explore the gastronomic delights, immerse yourself in a vibrant atmosphere filled with live music, performances, and engaging activities for all ages. From mouthwatering treats to captivating shows, our Food and Entertainment Fair is the perfect blend of culinary excitement and live entertainment. Join us for a delightful experience that promises to satisfy your cravings and ignite your senses. It\'s a feast for the taste buds and a celebration of entertainment – an event not to be missed!', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(8, NULL, 20, 5, NULL, 'organizational', 'Rambakan: Student Publication Workshop', 'Dive into the world of journalism, editorial design, and digital storytelling as seasoned professionals share their insights and guide you through the intricacies of student publications. From honing your writing skills to mastering layout design, Rambakan offers a comprehensive workshop to elevate your contribution to the world of student journalism. Connect with like-minded individuals, exchange ideas, and leave with the tools needed to amplify your voice. Rambakan: Student Publication Workshop is not just a workshop; it\'s an opportunity to ignite passion, refine skills, and contribute meaningfully to the art of storytelling within the academic community.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(9, 1, NULL, 4, 5, 'departmental', 'Kindling: Gearing towards the Digital Future ', 'Immerse yourself in thought-provoking talks that explore the possibilities, challenges, and ethical considerations of our digital journey. Be part of a community passionate about shaping a future where technology enriches our lives and propels us towards new horizons. Kindling is not just an event; it\'s a collective journey towards understanding, embracing, and navigating the uncharted territories of the digital landscape. Get ready to be inspired, informed, and kindle the flame of curiosity as we gear up for the Digital Future together.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(10, NULL, NULL, 3, NULL, 'open', 'Job and Career Fair', 'Unlock the doors to endless possibilities at our Job and Career Fair! This event is your gateway to a world of opportunities, connecting eager job seekers with a diverse array of employers and career development resources. Whether you\'re a seasoned professional looking for new horizons or a recent graduate embarking on your career journey, the Job and Career Fair is the place to be.', 'upcoming', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(11, 7, NULL, 5, 6, 'departmental', 'EduVisions Symposium', 'From interactive workshops to engaging panel discussions, EduVisions Symposium offers a space for collaborative learning, networking, and envisioning the future of education. Embrace the opportunity to refine your teaching philosophy, ignite your passion for liberal arts, and cultivate the skills necessary to shape the minds of tomorrow. Join us on this intellectual odyssey, where education meets inspiration, and your journey towards becoming an empowered educator begins.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(12, NULL, 19, 6, 7, 'organizational', 'PhiloConclave: Navigating Wisdom\'s Horizon', 'Engage in riveting discussions led by esteemed philosophers and scholars who will navigate the vast horizon of wisdom. From ancient philosophical principles to modern existential dilemmas, the symposium promises to be a rich tapestry of ideas, fostering an environment where questions are encouraged, and the pursuit of knowledge is celebrated.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(13, NULL, NULL, 1, 8, 'university', 'Yuletide Joy Exchange: A Campus-Wide Gift Ext', 'Celebrate the festive spirit and spread the joy throughout our university with the Yuletide Joy Exchange! This heartwarming event invites students, faculty, and staff to partake in a campus-wide gift exchange, transforming our university into a winter wonderland of surprises and shared happiness.\r\n\r\nHere\'s how it works: Participants register for the exchange and are randomly paired with someone else in the university community. Each person then prepares a thoughtful and festive gift to exchange during our grand Yuletide gathering. The exchange isn\'t just about the gifts; it\'s an opportunity to build connections, share holiday cheer, and create lasting memories.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(14, NULL, NULL, 2, 9, 'open', 'Adivay Festival', 'Adivay Festival is a testament to the resilience, diversity, and unity of the Cordilleran people. Join us in this extraordinary celebration where culture, tradition, and community converge in a harmonious spectacle. Come and be part of the Adivay experience—an expression of pride and joy that resonates through the mountains and valleys of the Cordilleras.\r\n\r\n\r\n\r\n\r\n\r\n', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(15, 3, NULL, 5, 10, 'departmental', 'InnovateXperience: SEA Symposium', 'Embark on a journey of innovation and design at InnovateXperience, an immersive symposium crafted for students studying engineering and architecture. This dynamic event brings together the brightest minds, fostering collaboration, and pushing the boundaries of creativity in the realms of engineering and architectural design.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(16, NULL, 10, 5, 11, 'organizational', 'DiscourseFest: Where Ideas Collide', 'Calling all debaters and discourse enthusiasts to DiscourseFest—an exhilarating event designed for the sharpest minds in the college debate community. Immerse yourself in a day of intellectual sparring, collaborative exchange, and a celebration of the power of persuasive discourse. \r\n\r\nDiscourseFest is more than a competition; it\'s a celebration of the power of words, the art of persuasion, and the intellectual camaraderie within the college debate community. Join us for a day of spirited discourse, where ideas collide, perspectives are challenged, and intellectual sparks ignite the flame of knowledge.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(17, NULL, NULL, 1, 12, 'university', 'WinterFest Extravaganza: A December Delight', 'Get ready to embrace the magic of the season at WinterFest Extravaganza—an enchanting university-wide event that transforms our campus into a winter wonderland of joy and festivities. As the semester winds down, come together with fellow students, faculty, and staff to celebrate the spirit of December in a grand and heartwarming fashion.\r\n\r\nWinterFest Extravaganza is a celebration that brings the entire university community together, fostering a sense of warmth, unity, and joy during the December season. Join us for a day of shared merriment and create lasting memories as we bid farewell to the year on a festive note.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(18, NULL, NULL, 7, 13, 'open', 'Street Spectacle: A Midtown Carnival Fiesta', 'Immerse yourself in the electrifying atmosphere of Street Spectacle, a city carnival right in the heart of midtown! This vibrant event transforms the bustling street into a dynamic celebration featuring pop-up performances by local artists, a diverse array of food trucks, an open-air art gallery, community market stalls, mobile workshops, live street murals, and gaming zones. Join us in turning the road into a lively fiesta that embraces community spirit, creativity, and the joy of shared experiences, all unfolding in the middle of the city\'s heartbeat.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(19, 6, NULL, 1, 14, 'departmental', 'HealthExpo 360: Unveiling the Science of Well', 'Dive into the interconnected realms of healthcare, wellness, and biological science at HealthExpo 360—an engaging event tailored for nursing, allied health, and biological science students. Explore cutting-edge health technologies, participate in hands-on wellness workshops, and attend a biological science symposium showcasing breakthrough research. Connect with allied health professionals at an expo, enhance nursing skills at interactive stations, and peruse a health and wellness fair. HealthExpo 360 is a comprehensive journey that offers insights, hands-on experiences, and valuable connections across the diverse landscape of health sciences, fostering a holistic approach to well-being.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(20, NULL, 3, 11, 15, 'organizational', 'EcoFest: Harmony in the Park', 'Embark on a green journey at EcoFest: Harmony in the Park, an eco-conscious event designed to inspire environmental stewardship and a deeper connection with nature. Join workshops on sustainable living, adopt native plants, and explore an upcycling fair. Listen to experts discuss environmental issues, participate in a park cleanup, and peruse a sustainable marketplace. Engage with eco-friendly art installations conveying powerful messages about conservation. EcoFest is a celebration of collective action, inviting participants to actively contribute to the well-being of Mother Earth and fostering a commitment to sustainable practices in the serene setting of the park.', 'ongoing', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(21, NULL, NULL, 10, 16, 'open', 'Urban Nexus: City Square Exhibition', 'Immerse yourself in the diverse tapestry of Urban Nexus, a dynamic event transforming the city square into an interactive hub of exhibits, seamlessly blending nature, innovation, and community engagement. Explore captivating displays such as the Nature Discovery Pavilion, highlighting local ecosystems, and the Green Innovations Showcase, unveiling sustainable technologies. Engage with wildlife conservation experts, witness an outdoor art gallery merging creativity with nature, and participate in hands-on science exhibits. Urban Nexus is not merely an event; it\'s a vibrant celebration of knowledge, culture, and environmental consciousness, where the city square becomes a nexus for exploration and community connection.', 'done', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(22, 4, NULL, 5, 17, 'departmental', 'Legal Luminary Symposium', 'Embark on a legal journey at the Legal Luminary Symposium, a dynamic event tailored for law students. Engage with keynote addresses from legal experts, participate in interactive panel discussions covering emerging legal trends, and witness the intensity of a moot court showdown. Connect with law firms and professionals at the career fair, explore the intersection of law and technology at the legal tech expo, and enhance your trial advocacy skills through a hands-on mock trial workshop. Legal Luminary Symposium is more than an event; it\'s a unique opportunity for law students to gain insights, network with professionals, and navigate the complexities of the ever-evolving legal landscape. Join us for a day of enlightenment and exploration as we collectively navigate the juridical horizon.', 'done', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(23, NULL, 18, 9, 18, 'organizational', 'Global Fusion Fiesta: A Cultural Kaleidoscope', 'Embark on a cultural odyssey at the Global Fusion Fiesta, an enchanting event designed for the vibrant tapestry of our international students\' organization. This fiesta celebrates diversity and fosters cross-cultural connections through a kaleidoscope of experiences, featuring traditional dance performances, international cuisine showcases, language exchange corners, and a cultural fashion parade. Engage in interactive workshops highlighting unique customs and traditions, and partake in a global talent showcase where students can share their cultural talents. This immersive event is a celebration of unity in diversity, offering a platform for international students to forge lasting connections, showcase their rich heritage, and create cherished memories in an atmosphere of shared understanding and appreciation.', 'done', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(24, NULL, NULL, 1, 19, 'university', 'OctoberFest Spectacular: A Harvest of Harmony', 'Raise your steins and join the revelry at the OctoberFest Spectacular, a celebration of fall flavors and camaraderie. Immerse yourself in the vibrant atmosphere with a vast selection of craft beers, live music, and traditional Bavarian delicacies. The festival grounds will come alive with the clinking of glasses, the sounds of laughter, and the aroma of hearty brews. Engage in lively games, from stein-holding competitions to bratwurst-eating contests. With a backdrop of autumn foliage, OctoberFest Spectacular promises an unforgettable experience, blending the best of beer culture and seasonal festivities in a spirited celebration that will leave you toasting to the joys of fall.', 'done', );
INSERT INTO `events` (`eventID`, `depID`, `orgID`, `venueID`, `scheduleID`, `eventCategory`, `eventName`, `description`, `eventStatus`, `event_img`) VALUES
(25, NULL, NULL, 8, 20, 'open', 'Harmony Unveiled: A Musical Journey of Love', 'Embark on an enchanting evening at \"Harmony Unveiled,\" a musical play that beautifully weaves together the compelling narratives of love, acceptance, and the vibrant spectrum of LGBTQ+ experiences. This riveting production, set to an evocative musical score, explores the journeys of diverse characters navigating the complexities of identity, relationships, and self-discovery. As the melodies unfold, audiences will be immersed in a tapestry of emotions, celebrating the resilience, joy, and universal themes that resonate within the LGBTQ+ community. \"Harmony Unveiled\" promises to be a captivating celebration of love\'s many forms, inviting everyone to embrace the power of acceptance and understanding through the universal language of music and storytelling.', 'done', );
/*!40000 ALTER TABLE `events` ENABLE KEYS */;
UNLOCK TABLES;

